"""Decorator to convert synchronous functions to async using asyncio.to_thread."""

import asyncio
import functools
import time
from typing import Any, Callable, TypeVar

F = TypeVar("F", bound=Callable[..., Any])


def sync_to_async(func: F) -> Callable[..., Any]:
    """Convert a synchronous function into an async coroutine.

    Runs the wrapped function in a separate thread via asyncio.to_thread,
    keeping the event loop free for other tasks.

    Usage::

        @sync_to_async
        def blocking_io():
            time.sleep(1)
            return "done"

        async def main():
            result = await blocking_io()
    """

    @functools.wraps(func)
    async def wrapper(*args: Any, **kwargs: Any) -> Any:
        return await asyncio.to_thread(func, *args, **kwargs)

    return wrapper


# ---------------------------------------------------------------------------
# Usage examples
# ---------------------------------------------------------------------------

@sync_to_async
def fetch_data(url: str) -> str:
    """Simulate a blocking network call."""
    time.sleep(0.1)
    return f"data from {url}"


@sync_to_async
def compute_heavy(n: int) -> int:
    """Simulate a CPU-bound computation."""
    total = 0
    for i in range(n):
        total += i * i
    return total


@sync_to_async
def read_file(path: str) -> str:
    """Read a file synchronously, expose as async."""
    with open(path) as f:
        return f.read()


# ---------------------------------------------------------------------------
# Tests
# ---------------------------------------------------------------------------

def test_sync_to_async_returns_coroutine():
    @sync_to_async
    def greet(name: str) -> str:
        return f"hello {name}"

    result = greet("world")
    assert asyncio.iscoroutine(result), "wrapper must return a coroutine"
    result.close()


def test_sync_to_async_preserves_name():
    @sync_to_async
    def original_name() -> None:
        pass

    assert original_name.__name__ == "original_name"


def test_sync_to_async_preserves_docstring():
    @sync_to_async
    def documented():
        """My docstring."""
        pass

    assert documented.__doc__ == "My docstring."


def test_sync_to_async_passes_args_and_kwargs():
    @sync_to_async
    def add(a: int, b: int, offset: int = 0) -> int:
        return a + b + offset

    result = asyncio.run(add(1, 2, offset=10))
    assert result == 13


def test_sync_to_async_propagates_exception():
    @sync_to_async
    def fail():
        raise ValueError("boom")

    try:
        asyncio.run(fail())
        assert False, "should have raised"
    except ValueError as e:
        assert "boom" in str(e)


def test_sync_to_async_concurrent_execution():
    """Two decorated sleep(0.1) calls should finish in ~0.1s, not ~0.2s."""

    @sync_to_async
    def slow():
        time.sleep(0.1)
        return "ok"

    async def run_both():
        results = await asyncio.gather(slow(), slow())
        return results

    start = time.monotonic()
    results = asyncio.run(run_both())
    elapsed = time.monotonic() - start

    assert results == ["ok", "ok"]
    assert elapsed < 0.19, f"expected concurrency, took {elapsed:.2f}s"


def test_sync_to_async_with_class_method():
    class Parser:
        @sync_to_async
        def parse(self, text: str) -> list[str]:
            return text.split()

    result = asyncio.run(Parser().parse("hello world"))
    assert result == ["hello", "world"]


if __name__ == "__main__":
    # Run tests
    tests = [v for k, v in globals().items() if k.startswith("test_")]
    for t in tests:
        t()
        print(f"PASSED: {t.__name__}")

    # Run examples
    async def demo():
        print(await fetch_data("https://example.com"))
        print(await compute_heavy(1000))

    asyncio.run(demo())
